DROP POLICY inspiration_read ON public.cultural_inspirations;
CREATE POLICY inspiration_read ON public.cultural_inspirations FOR SELECT TO authenticated USING (trip_private.feature_on(trip_id,'inspiration') AND trip_private.is_trip_member(trip_id,auth.uid()) AND (creator_id=auth.uid() OR partner_id=auth.uid() OR (reveal_on<=CURRENT_DATE AND hidden_at IS NULL AND EXISTS(SELECT 1 FROM public.culture_stamps st WHERE st.card_id=id AND st.user_id=auth.uid()))));
CREATE OR REPLACE FUNCTION public.culture_quest_previews() RETURNS TABLE(id uuid,trip_id uuid,creator_id uuid,partner_id uuid,category text,title text,photo_path text,quest_length text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.trip_id,c.creator_id,c.partner_id,c.category,c.title,c.photo_path,c.quest_length FROM public.cultural_inspirations c WHERE auth.uid() IS NOT NULL AND c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) $$;
REVOKE ALL ON FUNCTION public.culture_quest_previews() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.culture_quest_previews() TO authenticated;